$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
. (Join-Path $root 'validation/custom-app-production-dual-id-bridge-aware-spicetify-apply-executor-v0.1.0/test_custom_app_production_dual_id_bridge_aware_spicetify_apply_executor.ps1')
. (Join-Path $root 'validation/custom-app-production-post-apply-commit-cleanup-v0.1.0/custom-app-production-post-apply-commit-cleanup.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-dual-id-bridge-aware-post-apply-commit-cleanup.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-dual-id-bridge-aware-post-apply-commit-cleanup-now-compat-v0.1.1.ps1')

function Assert-DBACTrue([bool]$Value,[string]$Message){if(-not$Value){throw $Message}}
function Assert-DBACFalse([bool]$Value,[string]$Message){if($Value){throw $Message}}
function Assert-DBACEq($Actual,$Expected,[string]$Message){if([string]$Actual-cne[string]$Expected){throw "$Message actual=<$Actual> expected=<$Expected>"}}
function Copy-DBAC($Value){return (($Value|ConvertTo-Json -Depth 80)|ConvertFrom-Json)}
function Assert-DBACNoAuthority($Value,[string]$Label){foreach($f in @('result_is_authority','apply_execution_authorized','spicetify_apply_authorized','cleanup_authorized','additional_mutation_authorized','production_execution_authorized','production_mutation_authorized')){if($Value.PSObject.Properties[$f]){Assert-DBACFalse([bool]$Value.$f)("$Label escaped $f")}}}

$script:DBACFault=$null
function Invoke-CustomAppProductionDualIdBridgeAwarePostApplyCommitCleanupValidationHookV010 {
    param([Parameter(Mandatory=$true)][string]$Checkpoint,[Parameter(Mandatory=$true)]$Context)
    if(-not[string]::IsNullOrWhiteSpace([string]$script:DBACFault)-and$Checkpoint-ceq$script:DBACFault){throw ('DBAC_SIMULATED_PROCESS_DEATH_'+$Checkpoint)}
}
function New-DBACFixtureV010 {
    param([Parameter(Mandatory=$true)][string]$Label)
    $x=New-DBAXFixtureV010 ('dbac-'+$Label);$countPath=Join-Path $fakeDir ('dbac-'+$Label+'-count.txt');$apply=Invoke-DBAXV010 -X $x -CountPath $countPath
    Assert-DBACTrue($null-ne$apply-and[bool]$apply.ok)("apply fixture denied ${Label}: $([string]$apply.reason)");Assert-DBACTrue((Get-DBAXCountV010 $countPath)-eq1)("apply fixture count drift ${Label}")
    $f=$x.q.f
    return [pscustomobject]@{x=$x;f=$f;apply=$apply.result;count_path=$countPath;stage_workspace=[string]$f.x.generic.stage_workspace_path;app_container=[IO.Path]::GetDirectoryName([string]$f.x.generic.app_backup_path);persistence_backup=[string]$f.x.generic.persistence_backup_path}
}
function Invoke-DBACV010 {
    param([Parameter(Mandatory=$true)]$X,[AllowNull()]$Apply=$null,[DateTimeOffset]$Now=[DateTimeOffset]::UtcNow)
    if($null-eq$Apply){$Apply=$X.apply};$f=$X.f
    return Invoke-CustomAppProductionDualIdBridgeAwarePostApplyCommitCleanupV010 -DualIdApplyResult $Apply -DualIdFinalizationResult $X.x.q.final.result -DurableBridgeIntegrationResult $f.bridge.result -EvidenceBoundAtomicResult $f.atomic -GenericPreparedResult $f.x.generic -GenericStageExecutorResult $f.x.fixture.q.stage.result -Permit $f.x.fixture.q.x.permit -Name $f.name -LifecycleRow $f.x.fixture.q.x.f.lifecycle -ProvenanceRow $f.x.fixture.q.x.f.provenance -BindingRow $f.x.fixture.q.x.f.binding -AllowedRoot $f.trust -JournalStoreDirectory $f.store -ConsumptionStoreDirectory $f.x.fixture.q.x.store.store -SessionKey $script:DBAPSessionKey -LocalAppDataRoot ([string]$f.x.fixture.q.persistence.local) -AppDataRoot ([string]$f.x.fixture.q.persistence.roaming) -Now $Now
}
function Read-DBACJournalV010($X){return Read-CustomAppProductionCrashJournalV010 -AllowedRoot $X.f.trust -StoreDirectory $X.f.store}
function Assert-DBACApplyVerifiedUntouchedV010($X,[string]$Label){$j=Read-DBACJournalV010 $X;Assert-DBACEq([string]$j.entry.phase)'apply-verified' "$Label journal phase";Assert-DBACTrue(Test-Path -LiteralPath $X.stage_workspace)"$Label stage workspace removed";Assert-DBACTrue(Test-Path -LiteralPath $X.app_container)"$Label app backup removed";Assert-DBACTrue(Test-Path -LiteralPath $X.persistence_backup)"$Label persistence backup removed";Assert-DBACTrue((Get-DBAXCountV010 $X.count_path)-eq1)"$Label executed extra apply"}
function Assert-DBACCommittedV010($X,$Result,[string]$Label){Assert-DBACTrue([bool]$Result.ok)("$Label cleanup denied: $([string]$Result.reason)");Assert-DBACTrue((Get-DBAXCountV010 $X.count_path)-eq1)"$Label cleanup executed extra apply";Assert-DBACFalse(Test-Path -LiteralPath $X.stage_workspace)"$Label stage workspace remained";Assert-DBACFalse(Test-Path -LiteralPath $X.app_container)"$Label app backup remained";Assert-DBACFalse(Test-Path -LiteralPath $X.persistence_backup)"$Label persistence backup remained";$j=Read-DBACJournalV010 $X;Assert-DBACEq([string]$j.entry.phase)'committed-clean' "$Label journal phase";Assert-DBACEq([string]$j.entry.cleanup_result_fingerprint).Trim().ToLowerInvariant()([string]$Result.result.cleanup_fingerprint).Trim().ToLowerInvariant() "$Label cleanup fingerprint";Assert-DBACEq([string]$j.transaction_id).Trim().ToLowerInvariant()([string]$Result.result.journal_transaction_id).Trim().ToLowerInvariant() "$Label journal id";Assert-DBACFalse(([string]$Result.result.permit_transaction_id)-ceq([string]$Result.result.journal_transaction_id))"$Label transaction namespaces conflated";$rc=Test-CustomAppProductionDualIdBridgeAwarePostApplyCommitCleanupResultV010 $Result.result;Assert-DBACTrue([bool]$rc.ok)("$Label result validator denied: $([string]$rc.reason)");$ev=Read-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $X.f.trust -StoreDirectory $X.f.store -ExpectedTransactionId ([string]$Result.result.journal_transaction_id);Assert-DBACTrue($null-ne$ev-and[bool]$ev.ok)"$Label recovery evidence missing";Assert-DBACNoAuthority $Result "$Label wrapper";Assert-DBACNoAuthority $Result.result "$Label result"}

$count=0

# 1. Normal success: cleanup-starting is durable before any delete, all bounded artifacts disappear, committed-clean is durable, no extra apply. Explicit -Now is exercised by every cleanup call.
$script:DBACFault=$null;$x1=New-DBACFixtureV010 'success'
$stageSibling=Join-Path ([IO.Path]::GetDirectoryName($x1.stage_workspace)) ('keep-stage-'+[Guid]::NewGuid().ToString('N'));$appSibling=Join-Path ([IO.Path]::GetDirectoryName($x1.app_container)) ('keep-app-'+[Guid]::NewGuid().ToString('N'));$persistSibling=Join-Path ([IO.Path]::GetDirectoryName($x1.persistence_backup)) ('keep-persist-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($stageSibling)|Out-Null;[IO.Directory]::CreateDirectory($appSibling)|Out-Null;[IO.Directory]::CreateDirectory($persistSibling)|Out-Null
$r1=Invoke-DBACV010 $x1;Assert-DBACCommittedV010 $x1 $r1 'success';Assert-DBACTrue(Test-Path -LiteralPath $stageSibling)'success stage sibling deleted';Assert-DBACTrue(Test-Path -LiteralPath $appSibling)'success app sibling deleted';Assert-DBACTrue(Test-Path -LiteralPath $persistSibling)'success persistence sibling deleted';$count++

# 2. Crash after cleanup-starting before deletion: durable housekeeping-only phase, no artifact change, retry commits clean.
$script:DBACFault='after-cleanup-starting-barrier';$x2=New-DBACFixtureV010 'crash-after-start';$r2=Invoke-DBACV010 $x2;Assert-DBACFalse([bool]$r2.ok)'crash-after-start unexpectedly succeeded';Assert-DBACTrue([bool]$r2.cleanup_starting_persisted)'crash-after-start missing durable barrier';Assert-DBACTrue([bool]$r2.requires_idempotent_cleanup_resume)'crash-after-start missing resume requirement';$j2=Read-DBACJournalV010 $x2;Assert-DBACEq([string]$j2.entry.phase)'cleanup-starting' 'crash-after-start journal';Assert-DBACTrue(Test-Path -LiteralPath $x2.stage_workspace)'crash-after-start stage removed';Assert-DBACTrue(Test-Path -LiteralPath $x2.app_container)'crash-after-start app removed';Assert-DBACTrue(Test-Path -LiteralPath $x2.persistence_backup)'crash-after-start persistence removed';$script:DBACFault=$null;$r2b=Invoke-DBACV010 $x2;Assert-DBACCommittedV010 $x2 $r2b 'crash-after-start retry';$count++

# 3. Crash after stage deletion: only stage is gone; retry accepts already-absent and finishes without rollback/apply.
$script:DBACFault='after-stage-cleanup';$x3=New-DBACFixtureV010 'crash-after-stage';$r3=Invoke-DBACV010 $x3;Assert-DBACFalse([bool]$r3.ok)'crash-after-stage unexpectedly succeeded';Assert-DBACFalse(Test-Path -LiteralPath $x3.stage_workspace)'crash-after-stage stage remained';Assert-DBACTrue(Test-Path -LiteralPath $x3.app_container)'crash-after-stage app removed early';Assert-DBACTrue(Test-Path -LiteralPath $x3.persistence_backup)'crash-after-stage persistence removed early';Assert-DBACTrue([bool]$r3.requires_idempotent_cleanup_resume)'crash-after-stage missing resume';$script:DBACFault=$null;$r3b=Invoke-DBACV010 $x3;Assert-DBACCommittedV010 $x3 $r3b 'crash-after-stage retry';Assert-DBACEq([string]$r3b.result.stage_cleanup_status)'already-absent' 'crash-after-stage retry stage status';$count++

# 4. Crash after app-backup deletion: stage+app absent, persistence remains; retry finishes idempotently.
$script:DBACFault='after-app-backup-cleanup';$x4=New-DBACFixtureV010 'crash-after-app';$r4=Invoke-DBACV010 $x4;Assert-DBACFalse([bool]$r4.ok)'crash-after-app unexpectedly succeeded';Assert-DBACFalse(Test-Path -LiteralPath $x4.stage_workspace)'crash-after-app stage remained';Assert-DBACFalse(Test-Path -LiteralPath $x4.app_container)'crash-after-app app remained';Assert-DBACTrue(Test-Path -LiteralPath $x4.persistence_backup)'crash-after-app persistence removed early';$script:DBACFault=$null;$r4b=Invoke-DBACV010 $x4;Assert-DBACCommittedV010 $x4 $r4b 'crash-after-app retry';Assert-DBACEq([string]$r4b.result.stage_cleanup_status)'already-absent' 'crash-after-app stage status';Assert-DBACEq([string]$r4b.result.app_backup_cleanup_status)'already-absent' 'crash-after-app app status';$count++

# 5. Crash after persistence deletion before postcheck/commit: every transaction artifact absent but journal stays cleanup-starting; retry can still finalize committed-clean.
$script:DBACFault='after-persistence-backup-cleanup';$x5=New-DBACFixtureV010 'crash-after-persistence';$r5=Invoke-DBACV010 $x5;Assert-DBACFalse([bool]$r5.ok)'crash-after-persistence unexpectedly succeeded';Assert-DBACFalse(Test-Path -LiteralPath $x5.stage_workspace)'crash-after-persistence stage remained';Assert-DBACFalse(Test-Path -LiteralPath $x5.app_container)'crash-after-persistence app remained';Assert-DBACFalse(Test-Path -LiteralPath $x5.persistence_backup)'crash-after-persistence persistence remained';$j5=Read-DBACJournalV010 $x5;Assert-DBACEq([string]$j5.entry.phase)'cleanup-starting' 'crash-after-persistence journal';$script:DBACFault=$null;$r5b=Invoke-DBACV010 $x5;Assert-DBACCommittedV010 $x5 $r5b 'crash-after-persistence retry';Assert-DBACEq([string]$r5b.result.stage_cleanup_status)'already-absent' 'crash-after-persistence stage status';Assert-DBACEq([string]$r5b.result.app_backup_cleanup_status)'already-absent' 'crash-after-persistence app status';Assert-DBACEq([string]$r5b.result.persistence_backup_cleanup_status)'already-absent' 'crash-after-persistence persistence status';$count++

# 6. Rehashed permit-ID substitution remains structurally valid as an apply result but is denied before cleanup-starting/deletion.
$script:DBACFault=$null;$x6=New-DBACFixtureV010 'permit-id-drift';$bad6=Copy-DBAC $x6.apply;$bad6.permit_transaction_id=('0'*64);if([string]$bad6.permit_transaction_id-ceq[string]$bad6.journal_transaction_id){$bad6.permit_transaction_id=('1'*64)};$bad6.result_fingerprint=Get-CustomAppProductionDualIdBridgeAwareSpicetifyApplyExecutorSha256V010(Get-CustomAppProductionDualIdBridgeAwareSpicetifyApplyResultMaterialV010 $bad6);$v6=Test-CustomAppProductionDualIdBridgeAwareSpicetifyApplyResultV010 $bad6;Assert-DBACTrue([bool]$v6.ok)('permit drift fixture invalid: '+[string]$v6.reason);$r6=Invoke-DBACV010 -X $x6 -Apply $bad6;Assert-DBACFalse([bool]$r6.ok)'permit ID drift accepted';Assert-DBACApplyVerifiedUntouchedV010 $x6 'permit ID drift';$count++

# 7. Rehashed journal-ID substitution is denied before cleanup-starting/deletion.
$x7=New-DBACFixtureV010 'journal-id-drift';$bad7=Copy-DBAC $x7.apply;$bad7.journal_transaction_id=('0'*64);if([string]$bad7.journal_transaction_id-ceq[string]$bad7.permit_transaction_id){$bad7.journal_transaction_id=('1'*64)};$bad7.result_fingerprint=Get-CustomAppProductionDualIdBridgeAwareSpicetifyApplyExecutorSha256V010(Get-CustomAppProductionDualIdBridgeAwareSpicetifyApplyResultMaterialV010 $bad7);$v7=Test-CustomAppProductionDualIdBridgeAwareSpicetifyApplyResultV010 $bad7;Assert-DBACTrue([bool]$v7.ok)('journal drift fixture invalid: '+[string]$v7.reason);$r7=Invoke-DBACV010 -X $x7 -Apply $bad7;Assert-DBACFalse([bool]$r7.ok)'journal ID drift accepted';Assert-DBACApplyVerifiedUntouchedV010 $x7 'journal ID drift';$count++

# 8. Rehashed apply-evidence substitution is denied by durable journal evidence before cleanup-starting/deletion.
$x8=New-DBACFixtureV010 'apply-evidence-drift';$bad8=Copy-DBAC $x8.apply;$bad8.apply_evidence_fingerprint=('0'*64);if([string]$bad8.apply_evidence_fingerprint-ceq[string]$x8.apply.apply_evidence_fingerprint){$bad8.apply_evidence_fingerprint=('1'*64)};$bad8.result_fingerprint=Get-CustomAppProductionDualIdBridgeAwareSpicetifyApplyExecutorSha256V010(Get-CustomAppProductionDualIdBridgeAwareSpicetifyApplyResultMaterialV010 $bad8);$v8=Test-CustomAppProductionDualIdBridgeAwareSpicetifyApplyResultV010 $bad8;Assert-DBACTrue([bool]$v8.ok)('apply evidence drift fixture invalid: '+[string]$v8.reason);$r8=Invoke-DBACV010 -X $x8 -Apply $bad8;Assert-DBACFalse([bool]$r8.ok)'apply evidence drift accepted';Assert-DBACApplyVerifiedUntouchedV010 $x8 'apply evidence drift';$count++

$script:DBACFault=$null
if($count-ne8){throw "dual-ID post-apply cleanup matrix count mismatch $count"}
Write-Output "CUSTOM_APP_PRODUCTION_DUAL_ID_BRIDGE_AWARE_POST_APPLY_COMMIT_CLEANUP_PASS cases=$count parent_apply_matrix_replayed=true cleanup_starting_before_delete=true bounded_stage_app_persistence_delete=true partial_cleanup_resume=true committed_clean_durable=true explicit_now_contract=true no_extra_spicetify_apply=true permit_id_forward_only=true journal_id_recovery_only=true recovery_evidence_retained=true zero_authority=true"
